 204:   for (let i = 0; i < ops.length; i++) {
 205:     const fail = (reason) => {
 206:       throw new PatchError(`operation ${i}: ${reason}`, i);
 207:     };
 208:     const { op, path, from, value } = ops[i];
 209:     switch (op) {
 210:       case 'add':
 211:         result = addAt(result, path, deepCopy(value), fail);
