 59:     const [x, y] = stack.pop();
 60:     if (Array.isArray(x) || Array.isArray(y)) {
 61:       if (!Array.isArray(x) || !Array.isArray(y) || x.length !== y.length) return false;
 62:       for (let i = 0; i < x.length; i++) stack.push([x[i], y[i]]);
 63:     } else if (isObject(x) || isObject(y)) {
 64:       if (!isObject(x) || !isObject(y)) return false;
