 80: // Returns the array index a token names on `arr`, or throws.
 81: function arrayIndex(arr, token, notFound, allowEnd) {
 82:   if (!INDEX_RE.test(token)) throw new ApplyFailure(token === '-' ? notFound : 'bad index');
