165:   if (name === 'move' && isProperPrefix(from, path)) return { reason: 'cannot move into own child' };
166:   return {
167:     op: {
168:       name,
169:       path,
170:       from,
171:       value: usesValue ? op.value : undefined,
172:       // The ~0/~1 encoding is one-to-one, so equal pointer strings mean equal token lists.
173:       samePath: usesFrom && op.from === op.path,
174:     },
175:   };
176: }
177: 
178: function applyOperation(root, op) {
179:   switch (op.name) {
180:     case 'add':
181:       return add(root, op.path, deepCopy(op.value));
182:     case 'remove':
183:       remove(root, op.path, 'path not found');
184:       return root;
185:     case 'replace':
186:       return replace(root, op.path, deepCopy(op.value));
187:     case 'move': {
188:       if (op.samePath) {
189:         walk(root, op.from, 'from not found');
190:         return root;
191:       }
192:       const value = remove(root, op.from, 'from not found');
193:       return add(root, op.path, value);
194:     }
195:     case 'copy':
196:       return add(root, op.path, deepCopy(walk(root, op.from, 'from not found')));
197:     case 'test':
198:       if (!jsonEqual(walk(root, op.path, 'path not found'), op.value)) {
199:         throw new ApplyFailure('test failed');
200:       }
201:       return root;
202:   }
203: }
