205: export function applyPatch(doc, patch) {
206:   if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
207:   const ops = [];
208:   for (let i = 0; i < patch.length; i++) {
209:     const { reason, op } = checkOperation(patch[i]);
210:     if (reason) throw new PatchError(`operation ${i}: ${reason}`, i);
211:     ops.push(op);
212:   }
213:   let result = deepCopy(doc);
214:   for (let i = 0; i < ops.length; i++) {
215:     try {
216:       result = applyOperation(result, ops[i]);
217:     } catch (err) {
218:       if (err instanceof ApplyFailure) throw new PatchError(`operation ${i}: ${err.message}`, i);
219:       throw err;
220:     }
221:   }
222:   return result;
223: }
