131:   return removed;
132: }
133: 
134: function addAt(doc, tokens, value, fail) {
135:   if (tokens.length === 0) return value;
136:   const parent = follow(doc, tokens.slice(0, -1), 'path not found', fail);
137:   const key = tokens[tokens.length - 1];
138:   if (Array.isArray(parent)) {
139:     if (key === '-') {
140:       parent.push(value);
141:     } else if (!INDEX_RE.test(key)) {
142:       fail('bad index');
143:     } else if (Number(key) > parent.length) {
144:       fail('path not found');
145:     } else {
146:       parent.splice(Number(key), 0, value);
147:     }
148:   } else if (isObject(parent)) {
149:     setMember(parent, key, value);
150:   } else {
151:     fail('path not found');
152:   }
153:   return doc;
154: }
155: 
156: function sameTokens(a, b) {
157:   return a.length === b.length && a.every((token, i) => token === b[i]);
158: }
159: 
160: function isProperPrefix(prefix, tokens) {
161:   return prefix.length < tokens.length && prefix.every((token, i) => token === tokens[i]);
162: }
163: 
164: // Checks one operation against the form rules; returns its parsed form or a reason string.
165: function checkOperation(op) {
166:   if (op === null || typeof op !== 'object' || Array.isArray(op)) return 'not an object';
167:   const name = Object.hasOwn(op, 'op') ? op.op : undefined;
168:   if (typeof name !== 'string' || !OPS.has(name)) return 'bad op';
169:   const path = Object.hasOwn(op, 'path') && typeof op.path === 'string' ? tryParsePointer(op.path) : null;
170:   if (path === null) return 'bad path';
171:   const parsed = { op: name, path };
172:   if (name === 'move' || name === 'copy') {
173:     parsed.from = Object.hasOwn(op, 'from') && typeof op.from === 'string' ? tryParsePointer(op.from) : null;
174:     if (parsed.from === null) return 'bad from';
175:   }
176:   if (name === 'add' || name === 'replace' || name === 'test') {
177:     if (!Object.hasOwn(op, 'value')) return 'missing value';
178:     parsed.value = op.value;
179:   }
180:   if (name === 'remove' && path.length === 0) return 'cannot remove root';
181:   if (name === 'move' && isProperPrefix(parsed.from, path)) return 'cannot move into own child';
182:   return parsed;
183: }
184: 
185: function applyOperation(doc, { op, path, from, value }, fail) {
186:   switch (op) {
187:     case 'add':
188:       return addAt(doc, path, clone(value), fail);
189:     case 'remove':
190:       removeAt(doc, path, 'path not found', fail);
191:       return doc;
192:     case 'replace': {
193:       if (path.length === 0) return clone(value);
194:       const { parent, key } = locate(doc, path, 'path not found', fail);
195:       if (Array.isArray(parent)) parent[Number(key)] = clone(value);
196:       else setMember(parent, key, clone(value));
197:       return doc;
198:     }
199:     case 'move': {
200:       if (sameTokens(from, path)) {
201:         follow(doc, from, 'from not found', fail);
202:         return doc;
203:       }
204:       // The form rules guarantee `from` is not "" here, so it has a parent.
205:       const moved = removeAt(doc, from, 'from not found', fail);
206:       return addAt(doc, path, moved, fail);
207:     }
208:     case 'copy':
209:       return addAt(doc, path, clone(follow(doc, from, 'from not found', fail)), fail);
210:     case 'test':
211:       if (!deepEqual(follow(doc, path, 'path not found', fail), value)) fail('test failed');
212:       return doc;
213:   }
214: }
215: 
216: export function applyPatch(doc, patch) {
217:   if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
218:   const operations = [];
219:   for (let i = 0; i < patch.length; i++) {
220:     const checked = checkOperation(patch[i]);
221:     if (typeof checked === 'string') throw new PatchError(`operation ${i}: ${checked}`, i);
222:     operations.push(checked);
223:   }
224:   let result = clone(doc);
225:   operations.forEach((operation, i) => {
226:     const fail = (reason) => {
227:       throw new PatchError(`operation ${i}: ${reason}`, i);
228:     };
229:     result = applyOperation(result, operation, fail);
230:   });
231:   return result;
232: }
  1: #!/usr/bin/env node
  2: // Applies a JSON Patch to a JSON document: node jsonpatch-cli.mjs <patch> [<doc>]
  3: 
  4: import fs from 'node:fs';
  5: import { applyPatch, PatchError } from './jsonpatch.mjs';
  6: 
  7: const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
  8: const MAX_BYTES = 1048576;
  9: const MAX_DEPTH = 1000;
 10: const CHUNK_SIZE = 65536;
 11: 
 12: class CliError extends Error {
 13:   constructor(message, exitCode) {
 14:     super(message);
 15:     this.exitCode = exitCode;
 16:   }
 17: }
 18: 
 19: function fileError(code) {
 20:   if (code === 'ENOENT' || code === 'ENOTDIR') return 'no such file';
 21:   if (code === 'EISDIR') return 'is a directory';
 22:   return 'cannot read';
 23: }
 24: 
 25: function isDirectory(path) {
 26:   try {
 27:     return fs.statSync(path).isDirectory();
 28:   } catch {
 29:     return false;
 30:   }
 31: }
 32: 
 33: function readFileBytes(path) {
 34:   let fd;
 35:   try {
 36:     fd = fs.openSync(path, 'r');
 37:   } catch (err) {
 38:     const reason = fileError(err.code);
 39:     return reason === 'cannot read' && isDirectory(path) ? 'is a directory' : reason;
 40:   }
 41:   try {
 42:     if (fs.fstatSync(fd).isDirectory()) return 'is a directory';
 43:     const chunks = [];
 44:     let total = 0;
 45:     while (total <= MAX_BYTES) {
 46:       const chunk = Buffer.alloc(CHUNK_SIZE);
 47:       const n = fs.readSync(fd, chunk, 0, CHUNK_SIZE, null);
 48:       if (n === 0) break;
 49:       chunks.push(chunk.subarray(0, n));
 50:       total += n;
 51:     }
 52:     return total > MAX_BYTES ? 'too large' : Buffer.concat(chunks, total);
 53:   } catch (err) {
 54:     return fileError(err.code);
 55:   } finally {
 56:     fs.closeSync(fd);
 57:   }
 58: }
 59: 
 60: async function readStdinBytes() {
 61:   const chunks = [];
 62:   let total = 0;
 63:   try {
 64:     for await (const chunk of process.stdin) {
 65:       chunks.push(chunk);
 66:       total += chunk.length;
 67:       if (total > MAX_BYTES) return 'too large';
 68:     }
 69:   } catch {
 70:     return 'cannot read';
 71:   }
 72:   return Buffer.concat(chunks, total);
 73: }
 74: 
 75: // Depth of a parsed JSON value, computed without recursion.
 76: function exceedsDepth(value, limit) {
 77:   const stack = [[value, 1]];
 78:   while (stack.length > 0) {
 79:     const [current, depth] = stack.pop();
 80:     if (current === null || typeof current !== 'object') continue;
 81:     if (depth > limit) return true;
 82:     for (const child of Object.values(current)) stack.push([child, depth + 1]);
 83:   }
 84:   return false;
 85: }
 86: 
 87: async function loadJson(arg) {
 88:   const name = arg === '-' ? 'stdin' : arg;
 89:   const bytes = arg === '-' ? await readStdinBytes() : readFileBytes(arg);
 90:   if (typeof bytes === 'string') throw new CliError(`Error: ${name}: ${bytes}`, 1);
 91:   const hasBom = bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf;
 92:   let text;
 93:   try {
 94:     text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(hasBom ? bytes.subarray(3) : bytes);
 95:   } catch {
 96:     throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
 97:   }
 98:   let value;
 99:   try {
100:     value = JSON.parse(text);
101:   } catch {
102:     throw new CliError(`Error: ${name}: invalid JSON`, 3);
103:   }
104:   if (exceedsDepth(value, MAX_DEPTH)) throw new CliError(`Error: ${name}: too deep`, 3);
105:   return value;
106: }
107: 
108: async function main(args) {
109:   if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
110:   const [patchArg, docArg = '-'] = args;
111:   if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
112:   const patch = await loadJson(patchArg);
113:   const doc = await loadJson(docArg);
114:   let result;
115:   try {
116:     result = applyPatch(doc, patch);
117:   } catch (err) {
118:     if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
119:     throw err;
120:   }
121:   process.stdout.write(JSON.stringify(result, null, 2) + '\n');
122: }
123: 
124: // A closed stdout (for example `| head`) ends the run quietly instead of crashing.
125: process.stdout.on('error', () => {
126:   process.exitCode = 1;
127: });
128: 
129: main(process.argv.slice(2)).catch((err) => {
130:   if (!(err instanceof CliError)) throw err;
131:   process.stderr.write(err.message + '\n');
132:   process.exitCode = err.exitCode;
133: });

