import { after, before, describe, test } from 'node:test';
import fs from 'node:fs';
import path from 'node:path';
import {
  BOM,
  MAX_BYTES,
  expectError,
  expectOk,
  makeTmpDir,
  paddedJson,
  removeTmpDir,
  run,
  writeIn,
} from './helpers/cli-runner.mjs';

let dir;
let lockedDir;

before(() => {
  dir = makeTmpDir();
});

after(() => {
  if (lockedDir) fs.chmodSync(lockedDir, 0o755);
  removeTmpDir(dir);
});

describe('read errors', () => {
  test('ENOENT', () => {
    const p = path.join(dir, 'nope.json');
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('ENOENT for doc', () => {
    const p = writeIn(dir, 'r-p.json', '[]');
    const d = path.join(dir, 'nope-doc.json');
    expectError(run([p, d]), `Error: ${d}: no such file`, 1);
  });
  test('ENOTDIR', () => {
    const file = writeIn(dir, 'r-file.txt', '[]');
    const p = `${file}/x`;
    expectError(run([p]), `Error: ${p}: no such file`, 1);
  });
  test('directory as patch', () => {
    expectError(run([dir]), `Error: ${dir}: is a directory`, 1);
  });
  test('directory as doc', () => {
    const p = writeIn(dir, 'r-p2.json', '[]');
    expectError(run([p, dir]), `Error: ${dir}: is a directory`, 1);
  });
  test('directory with mode 000', () => {
    lockedDir = path.join(dir, 'locked');
    fs.mkdirSync(lockedDir);
    fs.chmodSync(lockedDir, 0o000);
    expectError(run([lockedDir]), `Error: ${lockedDir}: is a directory`, 1);
    fs.chmodSync(lockedDir, 0o755);
  });
  test('symlink loop is cannot read', () => {
    const loop = path.join(dir, 'loop');
    fs.symlinkSync('loop', loop);
    expectError(run([loop]), `Error: ${loop}: cannot read`, 1);
  });
  test('300-char file name is cannot read', () => {
    const p = path.join(dir, 'a'.repeat(300));
    expectError(run([p]), `Error: ${p}: cannot read`, 1);
  });
});

describe('size boundary', () => {
  test('exactly 1048576 bytes patch is OK', () => {
    const p = writeIn(dir, 's-p.json', paddedJson(MAX_BYTES));
    const d = writeIn(dir, 's-d.json', '[1]');
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('1048577 bytes patch is too large', () => {
    const p = writeIn(dir, 's-p2.json', paddedJson(MAX_BYTES + 1));
    expectError(run([p, path.join(dir, 'x')]), `Error: ${p}: too large`, 1);
  });
  test('exactly 1048576 bytes doc is OK', () => {
    const p = writeIn(dir, 's-p3.json', '[]');
    const d = writeIn(dir, 's-d3.json', paddedJson(MAX_BYTES));
    expectOk(run([p, d]), '[]\n');
  });
  test('1048577 bytes doc is too large', () => {
    const p = writeIn(dir, 's-p4.json', '[]');
    const d = writeIn(dir, 's-d4.json', paddedJson(MAX_BYTES + 1));
    expectError(run([p, d]), `Error: ${d}: too large`, 1);
  });
  test('BOM + 1048574 bytes (total 1048577) is too large', () => {
    const p = writeIn(dir, 's-p5.json', Buffer.concat([BOM, paddedJson(MAX_BYTES - 2)]));
    expectError(run([p, path.join(dir, 'x')]), `Error: ${p}: too large`, 1);
  });
  test('BOM + 1048573 bytes (total 1048576) is OK', () => {
    const p = writeIn(dir, 's-p6.json', Buffer.concat([BOM, paddedJson(MAX_BYTES - 3)]));
    const d = writeIn(dir, 's-d6.json', '[1]');
    expectOk(run([p, d]), '[\n  1\n]\n');
  });
  test('/dev/zero as patch is too large (bytes read, not stat size)', () => {
    expectError(run(['/dev/zero']), 'Error: /dev/zero: too large', 1);
  });
});

describe('stdin', () => {
  test('stdin over limit is too large', () => {
    const p = writeIn(dir, 'i-p.json', '[]');
    const input = Buffer.alloc(MAX_BYTES + 1, 0x20);
    expectError(run([p], { input }), 'Error: stdin: too large', 1);
  });
  test('stdin exactly at limit is OK', () => {
    const p = writeIn(dir, 'i-p2.json', '[]');
    expectOk(run([p], { input: paddedJson(MAX_BYTES) }), '[]\n');
  });
  test('stdin patch over limit is too large', () => {
    const d = writeIn(dir, 'i-d.json', '{}');
    const input = Buffer.alloc(MAX_BYTES + 1, 0x20);
    expectError(run(['-', d], { input }), 'Error: stdin: too large', 1);
  });
  test('stdin that is a directory is cannot read', () => {
    const p = writeIn(dir, 'i-p3.json', '[]');
    const fd = fs.openSync(dir, 'r');
    try {
      expectError(run([p], { stdio: [fd, 'pipe', 'pipe'] }), 'Error: stdin: cannot read', 1);
    } finally {
      fs.closeSync(fd);
    }
  });
});
import { describe, test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { CLI_PATH, expectOk, makeTmpDir, removeTmpDir, run, writeIn } from './helpers/cli-runner.mjs';

describe('CLI output formatting', () => {
  let dir;
  before(() => { dir = makeTmpDir(); });
  after(() => removeTmpDir(dir));

  test('output matches JSON.stringify(result, null, 2) for mixed values', () => {
    const doc = {
      s: 'a"\\\n?�', n: [-0, 1.5, 1e21, -3], e: [], o: {}, z: null, t: true, f: false,
      '__proto__': { 'k"y': [[], [{}], [1, [2, { a: 'b' }]]] }, 10: 'ten', 2: 'two',
    };
    const p = writeIn(dir, 'mixed-p.json', '[]');
    const d = writeIn(dir, 'mixed-d.json', JSON.stringify(doc));
    const expected = JSON.stringify(JSON.parse(JSON.stringify(doc)), null, 2);
    expectOk(run([p, d]), `${expected}\n`);
  });

  test('scalar documents print like JSON.stringify', () => {
    const p = writeIn(dir, 'scalar-p.json', '[]');
    for (const text of ['"x"', '-0', '0.1', 'null', 'false', '[]', '{}']) {
      expectOk(run([p, '-'], { input: text }), `${JSON.stringify(JSON.parse(text), null, 2)}\n`);
    }
  });

  test('a reader that closes stdout early gets one error line, not a stack trace', async () => {
    const p = writeIn(dir, 'pipe-p.json', '[]');
    const d = writeIn(dir, 'pipe-d.json', JSON.stringify(Array.from({ length: 100000 }, (_, i) => i)));
    const child = spawn(process.execPath, [CLI_PATH, p, d]);
    child.stdout.once('data', () => child.stdout.destroy());
    let stderr = '';
    child.stderr.on('data', (chunk) => { stderr += chunk; });
    const [code] = await once(child, 'close');
    assert.equal(stderr, 'Error: stdout: cannot write\n');
    assert.equal(code, 1);
  });

  // Native JSON.stringify overflows its stack at roughly 5000 levels.
  test('a valid patch that builds a result about 7000 levels deep still prints', () => {
    const level = 998; // a value this deep inside patch -> op keeps the patch at 1000
    const chain = (n) => `${'{"a":'.repeat(n - 1)}{"x":0}${'}'.repeat(n - 1)}`;
    const leafPath = `${'/a'.repeat(level - 1)}/x`;
    const patch = [];
    let path = leafPath;
    for (let i = 0; i < 6; i++) {
      patch.push({ op: 'replace', path, value: JSON.parse(chain(level)) });
      path += leafPath;
    }
    const p = writeIn(dir, 'deep-p.json', JSON.stringify(patch));
    const d = writeIn(dir, 'deep-d.json', chain(level));
    const res = run([p, d]);
    assert.equal(res.stderr, '');
    assert.equal(res.status, 0);
    // 7 * level objects: one opening line each, the "x" line, one closing line each.
    const objects = 7 * level;
    const lines = res.stdout.split('\n');
    assert.equal(lines.length, 2 * objects + 2);
    assert.equal(lines[objects], `${'  '.repeat(objects)}"x": 0`);
    assert.equal(lines.at(-2), '}');
    assert.equal(lines.at(-1), '');
  });
});
  });

  it('allows leading and trailing JSON whitespace', () => {
    const p = writeFile(dir, 'p10.json', ' \t\r\n[ ]\n\n ');
    const d = writeFile(dir, 'd10.json', '\n  {"a" : 1}\r\n');
    assertSuccess(run([p, d]), { a: 1 });
  });

  it('prints a result deeper than 1000 levels', () => {
    // Patch depth is 2 + 998 = 1000 and the doc is 1000 deep; the result is 1001 deep.
    const doc = JSON.parse('['.repeat(1000) + ']'.repeat(1000));
    const value = JSON.parse('['.repeat(998) + ']'.repeat(998));
    const p = writeFile(dir, 'p11.json', toJson([{ op: 'add', path: '/-', value }]));
    const d = writeFile(dir, 'd11.json', toJson(doc));
    const r = run([p, d]);
    assert.equal(r.status, 0);
    assert.equal(r.stderr, '');
    assert.equal(r.stdout.endsWith('\n'), true);
    const expectedDoc = JSON.parse(toJson(doc));
    expectedDoc.push(value);
    assert.equal(r.stdout, JSON.stringify(expectedDoc, null, 2) + '\n');
  });

  it('prints the same text as JSON.stringify for mixed nesting and escapes', () => {
    const doc = {
      '2': [1, -1.5e-7, 'q"\\\n\u0001', [], {}, [[{}]], null, true],
      '': { 'k"ey': { '?': false }, z: [] },
      b: [{ a: [{ b: {} }] }],
    };
    const p = writeFile(dir, 'p11b.json', '[]');
    const d = writeFile(dir, 'd11b.json', toJson(doc));
    assertSuccess(run([p, d]), doc);
  });

  it('prints a result too deep for JSON.stringify, made by repeated copy', async () => {
    // Each copy of the whole document into its deepest object doubles the depth: 875 * 8 = 7000,
    // past where the built-in JSON.stringify overflows the call stack (about 6000).
    const depth = 875;
    const doc = JSON.parse('{"a":'.repeat(depth - 1) + '{}' + '}'.repeat(depth - 1));
    const patch = [];
    let deepest = '/a'.repeat(depth - 1);
    for (let i = 0; i < 3; i++) {
      const target = `${deepest}/x`;
      patch.push({ op: 'copy', from: '', path: target });
      deepest = target + deepest;
    }
    const p = writeFile(dir, 'p11c.json', toJson(patch));
    const d = writeFile(dir, 'd11c.json', toJson(doc));
    // The output is about 100 MB of indentation, so stream it and keep only counts.
    const child = spawn(process.execPath, [CLI, p, d], { stdio: ['ignore', 'pipe', 'pipe'] });
    let stderr = '';
    let closers = 0;
    let tail = '';
    child.stderr.setEncoding('utf8').on('data', (c) => { stderr += c; });
    child.stdout.setEncoding('utf8').on('data', (c) => {
      for (const ch of c) if (ch === '}') closers++;
      tail = (tail + c).slice(-2);
    });
    const status = await new Promise((resolve) => child.on('close', resolve));
    assert.equal(stderr, '');
    assert.equal(status, 0);
    assert.equal(tail, '}\n');
    // Every copy doubles the number of objects: 875 * 8 objects, each closed once.
    assert.equal(closers, depth * 8);
  });
});

describe('closed stdout', () => {
  it('exits without a stack trace when the reader closes the pipe early', async () => {
    const p = writeFile(dir, 'p11d.json', '[]');
    const d = writeFile(dir, 'd11d.json', toJson(Array.from({ length: 100000 }, (_, i) => i)));
    const child = spawn(process.execPath, [CLI, p, d], { stdio: ['ignore', 'pipe', 'pipe'] });
    let stderr = '';
    child.stderr.setEncoding('utf8').on('data', (c) => { stderr += c; });
    child.stdout.once('data', () => child.stdout.destroy());
    const status = await new Promise((resolve) => child.on('close', resolve));
    assert.equal(stderr, '');
    assert.equal(status, 1);
  });
});

